export const SKILLS = {"framework":{"id":"88718ae4-2da7-57c4-9678-cea8d26cef2d","name":"Carnegie Skills Progressions","author":"Carnegie Foundation for the Advancement of Teaching","description":"A research-grounded durable skills framework from the Carnegie Foundation for the Advancement of Teaching and ETS. Volume 1 defines three capabilities — Collaboration, Communication, and Critical Thinking — across 11 subskills, 31 indicators, and 76 indicator items, each developing through four levels: Exploring, Analyzing, Integrating, and Extending.","license":"https://creativecommons.org/licenses/by/4.0/","attribution":"Knowledge Graph is provided by Learning Commons under the CC BY-4.0 license, available at https://creativecommons.org/licenses/by/4.0. Learning Commons received the Carnegie Skills Progressions curriculum under CC BY-4.0 from Carnegie Foundation for the Advancement of Teaching.","modified":"2026-07-07"},"levels":["Exploring","Analyzing","Integrating","Extending"],"skills":[{"code":"COL","name":"Collaboration","description":"Collaboration is the ability to work toward shared goals through engaging in effective communication, coordinating group efforts to integrate diverse perspectives while fostering interpersonal relationships. It involves exchanging ideas openly, regulating group activities, and prioritizing building trust and respect to enable groups to leverage individual strengths while maintaining focus on collective success.","subskills":[{"code":"COL.1","description":"Engage with ideas through intentional communication in service of shared goals","indicators":[{"id":"bd02c58c-76cd-51f4-ad43-9500c19f5353","code":"COL.1.1","description":"Develop comprehension or confirm understanding in multidimensional ways","items":[{"code":"COL.1.1A","levels":[["18d28a28-a972-59be-8311-0336e7a9df2b","Asks questions to better understand a topic, group task or shared goal."],["b273a816-11ac-5641-9fea-ddb3d34039ca","Asks questions to better understand group members' ideas."],["f272d6b1-11e9-5a5a-a233-541b635efea4","Asks questions to understand diverse ideas and perspectives, both in what group members think and why they hold certain views."],["0080c443-24b7-51b0-ad6e-692dd179eb9c","Asks questions that help the group understand and use diverse ideas and perspectives, including those from personal or cultural experiences (e.g., to create a combination of the group's ideas)."]]},{"code":"COL.1.1B","levels":[["3a08ce84-cce1-5551-a5dc-47f9360eb4f6","Acknowledges what group members have shared to ensure accurate understanding (e.g., restates information shared by group members to show basic understanding)."],["6a5e16f1-f2ab-5b7c-9cdf-ac3bb5975fa3","Considers group members' ideas in group discussions."],["c6da1200-d576-59fa-9df1-f4faed18481c","Considers others' ideas and shares suggestions to help the group move forward (e.g., uses ideas from other group members to show how contributions support the group work)."],["01a20ef5-1094-5acb-acb5-f2925971049d","Uses suggestions from the group to show how different ideas can be part of the group's final product (e.g., combines group members' ideas to create a new answer/solution for a next step or final product or to strengthen/refine existing work)."]]}]},{"id":"13274dbf-77db-5bc0-adc8-1fb843090ae7","code":"COL.1.2","description":"Embrace, respect and elevate diverse perspectives and ideas","items":[{"code":"COL.1.2A","levels":[["c717b80b-3ead-5fe5-87a2-ec2c57bd3cab","Acknowledges others' ideas (e.g., by restating). [Note intentional overlap with 1.1B and 1.2B.]"],["fcdb1658-4cfc-59f5-9fdc-8da909d11821","Listens intentionally by giving group members space to share their ideas without interruption, even when ideas are different."],["77e8f8a6-aa6f-5e91-af5a-3dc2fa06f42c","Adds group members' ideas to improve their own ideas, especially when their ideas are different."],["969df14a-0e24-59d1-b3b7-7cb71c7d9736","Compares and combines different ideas by showing how they are similar, different or strong in different ways."]]},{"code":"COL.1.2B","levels":[["af1b3735-5365-5bd3-a097-4509807d92b3","Contributes own unique ideas and perspectives to the task without referencing what others have said."],["30522e41-8623-5996-b477-9059385cfde2","Contributes ideas and resources to help group members work on different parts of the task."],["e39ec495-535e-5573-8fc9-d4ba15e51048","Connects their ideas with group members' ideas to help the group complete the task."],["44fd0d87-a423-5119-93a7-6933d2a2ba2b","Creates new ideas and solutions by combining different parts of group members' contributions."]]},{"code":"COL.1.2C","levels":[["e65158cf-8f22-5764-884f-59d50cceb749","Discusses ideas with the group."],["7c59b881-8532-55df-914f-5949b1e0ae6e","Uses intentional discussions to explore and understand different ideas without judgment."],["1e75db65-6237-5e6a-9729-dbb00db12552","Engages in debates/conflicts constructively and considers different viewpoints in an open discussion with group members."],["ccadaea9-be6f-5fc5-85da-1d0c3c6ede91","Engages in debates/conflicts constructively and works with group members to include different viewpoints in group solutions, and expresses vulnerability about their own viewpoints (e.g., recognizes flaws in their own views)."]]}]}]},{"code":"COL.2","description":"Effectively engage in and facilitate group activities and decision-making toward shared goal","indicators":[{"id":"747b5b92-7638-502a-9934-2f5a6bbe2a5f","code":"COL.2.1","description":"Flexibly establish and contribute to group ideas and team norms","items":[{"code":"COL.2.1A","levels":[["340d1ca2-1300-5ca9-bde6-0826c6fac903","Discusses and understands the purpose of the group (e.g., participates in early discussions about specific group goals, acknowledges the reasons a group has formed/come together)."],["373eeb29-00ba-5d51-984e-85c3a73a6e90","Contributes to developing group goals."],["de4b3119-c52f-5a5d-8ffc-0c9067d4bf1a","Helps explain group goals to make them clear and easy for everyone to understand (e.g., to confirm group understanding)."],["48887c12-6470-5b42-a8ef-de3c7eb13c49","Develops group goals and explains how they connect to everyone's strengths and abilities (e.g., takes part in discussion/analysis of connections between group goals and individuals' strengths)."]]},{"code":"COL.2.1B","levels":[["3bf52cd6-ae51-5639-aa20-9110101ea1a7","Helps create roles, responsibilities, and group norms for the group."],["208ceb74-fd48-5263-9f6f-195a32c2f452","Takes on assigned roles and responsibilities by completing tasks on time and helping others meet their commitments (e.g., takes on roles that reflect individual experiences and cultural strengths)."],["8d4f8ac6-9a31-5f86-b355-19e2d049c9f0","Contributes flexibly to support group goals, adopting roles in ways that reflect individual experiences, goals and cultural strengths."],["bee28fb1-a5ee-57b8-92dd-90fae24d557a","Facilitates group conversations to reflect and consider/reconsider whether roles are effectively contributing to group goals."]]},{"code":"COL.2.1C","levels":[["c5cbb7d8-bad4-5e78-8471-e24987c2f7b3","Shows respect by participating."],["3c9bf699-3efb-5e83-8c7d-68fcb637b4b2","Shows respect by letting others talk one at a time."],["0c63f5c8-b9cb-5bec-ad25-18ab8af90435","Shows respect by valuing others' ideas (e.g., addressing or using others' ideas) or giving helpful feedback."],["09078c59-cc4d-5fa4-814c-273e7f1f33a1","Shows respect by actively listening, trying to understand and use different perspectives, to advance group goals."]]}]},{"id":"8ba52e49-2eb8-53f8-a078-cc9ecfa6298f","code":"COL.2.2","description":"Check in and circle back with group progress","items":[{"code":"COL.2.2A","levels":[["dd00d711-fb72-530c-9542-206ed45849c8","Independently keeps track of personal work."],["3e857fc6-422e-54a7-80f1-5a79f514eb43","Shares updates on personal work when asked."],["3c5bc086-462f-50f9-9a3b-18fdc766f1e9","Discusses with others about whether the group is meeting its goals and shares ideas for improvement."],["b365e06a-11a5-5756-aea9-aebcc1b36d6e","Checks on the group's progress (e.g., by meeting regularly with the group) and suggests changes to goals or tools when needed."]]},{"code":"COL.2.2B","levels":[["c2efc655-a2cd-5763-9c4a-4b3758ba23de","Checks how personal work contributes to the group goals to ensure progress."],["a751bfe3-fcf2-53b9-802f-877c88f24dae","Uses feedback to help the group identify and solve problems."],["243abd54-96bf-5411-a9bc-278b46d621d1","Helps the group reflect on its overall progress toward its goals and identify areas for improvement."],["dbbc76c4-2416-5a43-ac04-f625d2f579c7","Identifies areas for improvement and facilitates the group to reflect on progress toward goals and any needed next steps."]]}]},{"id":"40b9f30f-27eb-5403-8371-c7d472fef1e9","code":"COL.2.3","description":"Adjust team processes and timeline","items":[{"code":"COL.2.3A","levels":[["a424c379-77ac-53f5-8b00-50d7609443aa","Identifies challenges that disrupt task completion."],["f7ad9316-0a79-5caf-94d8-ce83872423eb","Makes changes to personal tasks when challenges arise."],["9352c517-9d5a-50c7-bc03-51cdc9530ac1","Discusses with group members how the group can adapt in response to challenges (e.g., when current assignments present challenges)."],["3b7c066b-cc6f-592f-8a15-a3c5a3404d0a","Collaborates with team members to adjust next steps (e.g., adjust task assignments, create new timelines) to make progress toward group's goals."]]},{"code":"COL.2.3B","levels":[["3de71659-05f6-5112-83de-903ac95e9627","Identifies when there is a need for assistance to facilitate individual or group progress."],["0018a976-153d-5690-839b-ad76c6018386","Asks for assistance as needed to make progress toward group's goals."],["ea35ec57-9938-5be1-aa76-70c9dd1c5a34","Suggests ways to adjust working style or schedules to help group make progress toward group's goals."],["7ee7de10-a6db-5241-935a-e73c9fb6deb0","Suggests and uses new tools and strategies to make progress toward group's goals."]]}]}]},{"code":"COL.3","description":"Emphasize interpersonal relationships","indicators":[{"id":"96266f69-e724-5759-935c-64e88e5fff15","code":"COL.3.1","description":"Build trust","items":[{"code":"COL.3.1A","levels":[["a20c6fd7-d437-55f3-8c3e-7bf09c522420","Builds trust by knowing one's own strengths and using voice to choose a role according to their strengths."],["f7ee4979-2e5e-5981-a5b8-744a80e62ba8","Builds trust by keeping commitments to the group and completing tasks in a way that helps the group meet their commitments."],["a3b112ae-883e-5651-b9e8-95a4246a27e6","Builds trust by being open to feedback and adjusting tasks to help the group work."],["65b569f1-61b1-5b97-8f90-d4ee62497e03","Builds trust by making sure everyone feels valued and respected, even if they disagree (e.g., via discussions)."]]},{"code":"COL.3.1B","levels":[["23799cc5-47c3-5ae7-8b31-1cad20cc2416","Uses language with the intent of building shared understanding."],["b1cbfd3d-9e8f-5339-8e93-090327ddc8b7","Shows appreciation and respect for group members' efforts and contributions."],["8d1851a7-b2aa-58df-8bc8-feb15178f526","Uses positive, respectful, and kind language to create a supportive team environment."],["6fa0ee9a-e57a-5f95-8813-991df3074480","Gives helpful feedback and shows appreciation for others' efforts to foster a flexible team environment where members feel safe to express disagreements, ask hard questions, and engage in honest dialogues even when the discussion is challenging."]]}]},{"id":"e224f416-04af-59db-b16b-2733a95819a5","code":"COL.3.2","description":"Support team dynamics","items":[{"code":"COL.3.2A","levels":[["f4c67481-e7a2-52fa-8b55-0362562fb763","Understands their own communication preferences."],["110807bf-da33-54aa-83e0-091a72485523","Considers communication preferences of others in the group."],["8d69886a-3408-5617-b653-361a1dec7613","Adjusts to group members' communication preferences and/or styles."],["fdf55754-61b4-5c79-93f7-a93c8a3fd139","Demonstrates commitment (e.g., through interactions) to varied means of communication to create an inclusive environment."]]},{"code":"COL.3.2B","levels":[["92d4ec9c-1134-537f-ab21-33bde62a8f4b","Respectfully contributes to the group."],["3634c984-4add-5fff-9c26-a2691447bb75","Contributes to a flexible group environment by being dependable and respectful to the group."],["88e88d9a-f4b8-5cff-8913-24784d6d1c69","Helps keep a flexible group environment by being reliable and respectful, even when things are tough."],["22559879-8e0c-53fb-be4a-0938a3558fa1","Shows dependability and respect to others by solving problems and helping maintain a flexible group environment."]]},{"code":"COL.3.2C","levels":[["4319e6e7-e000-503a-aa6a-c05828daa59e","Joins discussions to keep the group going."],["6f8608fb-efa2-591a-ad8b-fb9de2248c2d","Participates actively and shares ideas to keep the group going."],["b6f94b57-a2c8-55e5-aca3-e3b20ded1d18","Listens to and adds on to ideas of others' to keep the group working."],["79fb6e62-4ad0-5cf6-a673-40b04ee07b9e","Provides helpful contributions to keep the group focused and productive, even if other group members are not productively contributing."]]}]}]}]},{"code":"COM","name":"Communication","description":"Communication skill is the ability to share and interpret messages that convey ideas, thoughts, opinions, knowledge and data with clarity and purpose using various modalities such as verbal, nonverbal (including gestures and body language), written, visual and listening, while adapting to diverse contexts and audiences.","subskills":[{"code":"COM.1","description":"Use multimodal forms of communication to effectively convey ideas (e.g., spoken, written, listening, visual, artistic, etc.).","indicators":[{"id":"1c61dc4c-f315-5112-a88a-e1fb91d0056a","code":"COM.1.1","description":"Refine messages to make ideas clearer","items":[{"code":"COM.1.1A","levels":[["7ed42607-c4ca-5b21-85a3-5ba546564915","Notices when a message might be unclear in some situations (e.g., by asking a question, stating that it is unclear, asking for information to be repeated when needed)."],["f3d3be84-5269-5adb-be7d-228ab0ee97bb","Identifies specific features of a message that are unclear."],["ebc84e01-6828-524b-9eb2-960ea65e0f06","Identifies how to improve unclear messages and explains rationale and strategies."],["cc6b01e5-bf54-53c2-9e51-b2f571822b4b","Analyzes messages for clarity across formats and explains strategies to improve them for diverse audiences."]]},{"code":"COM.1.1B","levels":[["1d5eccb8-d4a9-5884-977b-b958920e616f","Edits simple messages to express ideas more clearly."],["9c9a6600-f57b-5a4b-85f0-23afd2977a35","Edits messages to make ideas clear and easy to understand."],["0e22b2a1-adc1-56f4-a70e-06655d72a90a","Reviews and edits messages to make them clear, even involving creative ways of expression (e.g., literary devices)."],["5ead0d98-4c86-5e9c-a976-744c5ac76d0d","Applies revision strategies to clarify complex ideas and communicates them effectively across multiple modalities."]]},{"code":"COM.1.1C","levels":[["d261facf-bff0-5e89-9e87-fd916aff6120","Recognizes the importance of reducing unnecessary details in longer or complex messages (e.g., essays, presentations)."],["b38690a2-56ae-5d04-af12-1446eed0e50f","Applies strategies to improve clarity in longer or more complex messages (e.g., essays, presentations, videos, audio recordings)."],["87cb8b92-ba95-5b2e-991c-d850a5e3c6e8","Explains strategies to improve messages across multiple types of longer or more complex messages (e.g., essays, presentations, videos, audio recordings)."],["e8d962ce-b73e-5c66-b088-2a4fa0bc68ee","Explains strategies to improve messages across multiple types of longer or more complex messages (e.g., essays, presentations, videos, audio recordings), accounting for a range of audience and purposes."]]}]},{"id":"1680c8fc-fd64-5518-96bd-418ec7690937","code":"COM.1.2","description":"Share the same idea in different ways","items":[{"code":"COM.1.2A","levels":[["7ccc4a92-c5c6-5d8e-b821-4026e86c83de","Recognizes that the same idea can be expressed in at least two different ways."],["f408b6c3-5f07-527d-8bb1-4524096f092a","Identifies multiple ways to express the same idea."],["fc8d9c45-1e0b-523e-9a65-a4e31d964ed3","Explains multiple clear ways to express an idea, considering the audience and context."],["310e14fa-29eb-5173-83ed-6d357c89fe31","Demonstrates and models multiple effective ways to frame ideas across disciplines and contexts."]]},{"code":"COM.1.2B","levels":[["483ab701-b828-5c64-8107-176af9bd231e","Notices that others perceive ideas differently and begins adapting explanations."],["eeb67590-4f5f-5c30-9087-dc9165c1cc26","Adjusts explanations to align with different perspectives to improve understanding."],["bf7ad6b8-5389-51ac-9872-21f26de87d12","Explains how to tailor messages for multiple audience perspectives to ensure greater clarity."],["1d170fd2-f993-53da-8c85-a7f1cfea15d2","Supports others in adapting ideas for different audiences and evaluates effectiveness of those adaptations."]]},{"code":"COM.1.2C","levels":[["b7a3cd39-b04d-56c2-97a1-483d3438f57b","Selects a reasonable way to share ideas based on the audience and context."],["c76445f0-98ba-511f-a627-b15218824f9a","Selects a reasonable way to share an idea from several options after considering the audience and context."],["15bafc48-d8b7-5d05-99ec-9169ef87b37e","Evaluates features of the idea, audience, and context to choose a reasonable way to share an idea."],["c7b8756f-1e7b-510a-a827-9fa562c35da2","Leads others in analyzing and choosing effective communication approaches across shifting contexts."]]}]},{"id":"b343c48d-139e-5f57-86ea-9311f02e97dc","code":"COM.1.3","description":"Use multimodal communication to keep others interested","items":[{"code":"COM.1.3A","levels":[["8c08cbed-5681-523d-a682-e122cc6a974c","Notices how others react to a message."],["08514340-c000-573f-8696-692841796833","Observes reactions and adjusts manner of expression."],["de54bfa0-87bb-5bea-857a-f44dc8db016d","Adapts manner of expression to sustain engagement in diverse contexts."],["5d6ff6d2-6aeb-583e-8c57-b0193fbb582a","Facilitates engaging communication environments and mentors others in reading and responding to audience dynamics."]]},{"code":"COM.1.3B","levels":[["46fafd09-85d7-55a3-8d2d-7334cc224d76","Uses features of expression (e.g., gestures, modulation)."],["141a29ce-4f30-5355-b2b1-d248559d609e","Uses expressive features (e.g., gestures, modulation) to connect with audiences and make presentations interesting."],["16673f3b-0569-5aeb-8745-9e19bc98197c","Combines expressive features (e.g., gestures, modulation) to create presentations that are captivating for specific audiences."],["38170388-f86a-5ab7-99f3-9dd8d8157fcc","Combines expressive features (e.g., gestures, modulation) to create presentations that are captivating for various and diverse audiences."]]}]},{"id":"273bb926-7459-5690-9731-1881ef23bfef","code":"COM.1.4","description":"Use different tools to communicate","items":[{"code":"COM.1.4A","levels":[["6e159fb3-1a03-5807-83ed-c4793698e970","Uses some tools (e.g., text editing, presentation slides, social media, forums, messaging apps, translation tools, video/audio software, assistive technologies) to share ideas."],["960e641e-552e-55d4-9ef7-61f08d66fbb8","Uses a variety of tools (e.g., text editing, presentation slides, social media, forums, messaging apps, translation tools, video/audio software, assistive technologies) to share ideas clearly."],["e7e24d39-2ce3-564e-811f-67f69c50cdcc","Explains the rationale behind tool choices (e.g., text editing, presentation slides, social media, forums, messaging apps, translation tools, video/audio software, assistive technologies) across diverse communication tasks and audiences."],["565cb1c9-44dc-5a26-ad9c-91f532c8db2b","Uses a wide variety of tools (e.g., text editing, presentation slides, social media, forums, messaging apps, translation tools, video/audio software, assistive technologies) to make ideas clear and engaging while retaining their voice."]]},{"code":"COM.1.4B","levels":[["afd49d03-09a8-50c3-8440-364aaa59ed86","Notices that others prefer different tools for receiving information."],["f1c84528-5444-5e7d-8181-aa9953957303","Selects tools that align with audience preferences in certain contexts."],["211f65f5-f6a2-5c0e-bd1a-96c33e33c1a1","Evaluates the message, audience and context to select effective tools to convey a message in their own voice."],["d9a64c38-c815-5382-a375-dd4c12b29cb5","Evaluates the message, audience and context to select the most effective tools to convey a message in their own voice across a range of contexts and purposes."]]}]}]},{"code":"COM.2","description":"Adapt communication styles based on diverse audiences and contexts while conveying a message in one's true voice","indicators":[{"id":"05fbde5c-bee5-588f-a389-888b96b24e45","code":"COM.2.1","description":"Present ideas in a variety of settings and for a variety of purposes","items":[{"code":"COM.2.1A","levels":[["d020aa12-3ce1-59e6-b70a-c9321064052c","Notices that some presentations may have specific goals."],["dd9ad85f-0182-53e3-a05d-761918bd3658","Tailors content to fit different goals and settings (e.g., explaining, persuading)."],["cc0bb318-4825-5831-8377-0a32d5b2cdfe","Evaluates and refines content to meet nuanced goals in varied settings (e.g., persuasion, inquiry, storytelling)."],["c64979f5-4121-5711-89c3-6ccd62dcc49d","Demonstrates an understanding of the purpose of presentations and chooses specific ways to adjust content to match the nuanced goals of different settings or events (e.g., to explain, inform, persuade or entertain)."]]},{"code":"COM.2.1B","levels":[["8e23c4bb-bf59-5ea1-95c3-7c6e60a80ed3","Recognizes the importance of preparing before sharing ideas (e.g., preparing notes, practicing the presentations or key skills relevant for the presentation)."],["3511854f-68cd-5233-ad84-cf2a9c7c229a","Prepares before sharing ideas (e.g., has prepared notes, practiced the presentation or key skills relevant for the presentation, rehearsed delivery)."],["991702af-8e81-54e3-a660-78416872bd6b","Shares ideas effectively (e.g., has prepared notes, practiced the presentation or key skills relevant for the presentation, rehearsed delivery) without referring to or relying on notes."],["97a3f33a-88d3-5664-89f6-066bb8e06792","Designs and executes personalized preparation strategies to support clarity and audience connection."]]},{"code":"COM.2.1C","levels":[["9d36c6fd-082b-5d12-8d74-46796bc2b926","Presents ideas in certain familiar settings (e.g., class discussions, group projects, extracurricular activities)."],["98a7e1bf-772b-5d4e-afa3-caa25f5088ce","Presents ideas clearly in multiple settings, including somewhat new or unfamiliar settings."],["d8ece50f-fd7f-5302-b26f-ae59f1174467","Presents ideas clearly and naturally in various settings, including very new and unfamiliar settings (e.g., classes, group work or extracurricular events)."],["c889ab23-796e-522b-bd47-eaa8837c85c1","Presents ideas clearly and naturally in various settings, including very new and unfamiliar, formal and informal, and cross-context settings and scenarios (e.g., classes, group work or extracurricular events)."]]}]},{"id":"9ff10140-d99a-5eb2-901e-92cc05803391","code":"COM.2.2","description":"Identify the audience and context to adapt communication","items":[{"code":"COM.2.2A","levels":[["968f71d8-4b38-508c-b678-9a9a6f3351da","Recognizes the importance of making a message more interesting and relatable for certain audiences."],["2f404ae3-4319-58d9-86af-1f74dde8dcc4","Identifies ways to make a message clear and engaging for a given audience."],["af6358a1-d765-5f5b-867f-35b47f7dbbc5","Analyzes the audience within context and explains how specific communication strategies make a message better for different types of audiences."],["2a92181f-7d5c-501f-b259-30059dbaeac0","Anticipates subtle or unspoken needs of different audiences and adapts accordingly."]]},{"code":"COM.2.2B","levels":[["38085b98-1720-5929-895a-89db8353bc8a","Recognizes that the delivery of a message can be adjusted for an audience (e.g., modulation, use of examples)."],["5b95151a-3e28-500c-b251-35420246c791","Adjusts the delivery of a message to suit audience needs using relevant strategies (e.g., modulation, use of examples)."],["64024fda-36cb-56af-82eb-122b81249654","Adjusts the delivery of a message to suit the complex needs of different types of audience members (e.g., modulation, use of examples) while encouraging the audience to be receptive to the message."],["165d9624-beb1-5155-9af1-f9636f6ed86f","Synthesizes contextual and audience cues to shape effective delivery of a message across varied scenarios."]]}]},{"id":"16496078-c27f-5877-bba4-65a87b93e24c","code":"COM.2.3","description":"Demonstrate presentation skills","items":[{"code":"COM.2.3A","levels":[["544a9fab-0755-548a-a55a-de969b75eae0","Recognizes the importance of planning and organizing presentations to make a message clear."],["f497192d-0d84-5ed5-81fb-6a1d2cf21048","Plans and organizes presentations so the audience can follow and understand key points."],["f7dc5dfe-13f7-5890-bbdf-4012c836db0d","Plans, organizes and explains strategies for giving presentations that the audience may easily understand and follow."],["a9cebfe2-d816-59ca-a3e4-cf07dc626ab8","Adapts structure mid-presentation as needed to ensure coherence and responsiveness to audience feedback."]]},{"code":"COM.2.3B","levels":[["dbd07dc1-d97c-5abc-a324-448226e2bb7d","Demonstrates effort to remain confident while communicating with others."],["327eb593-7a07-55a5-8f45-f82ded0a31cc","Remains confident while communicating with others."],["c44887f8-a928-576f-b9ea-5798a75d3fc4","Remains confident and may use language devices (e.g., humor) to relieve tension or better connect with an audience."],["873a4958-a969-50b9-a3de-ec94e18d073d","Demonstrates presence and emotional intelligence in both planned and spontaneous presentations."]]},{"code":"COM.2.3C","levels":[["901c205d-5ae0-52fe-a30e-d15d69a23a0b","Uses multimodal features of expression (e.g., gestures, modulation)."],["76e09801-397e-56e7-bc51-84e28f82f97f","Combines multimodal features of expression (e.g., gestures, modulation) to enhance portions of the presentation."],["9e8c9cf4-3af4-57f7-91d8-f727209b3e29","Integrates multimodal features of expression (e.g., gestures, modulation) in an authentic manner to enhance portions of presentations while making them more engaging and personable."],["b8cb42cc-b6fd-58ba-a1b4-24496c1eee10","Synthesizes multimodal elements across settings, developing a compelling personal presentation style."]]}]}]},{"code":"COM.3","description":"Demonstrate active listening or comprehension","indicators":[{"id":"b798cf71-77fa-50f5-92ea-59bb6dbd75f6","code":"COM.3.1","description":"Listen to others for deeper meaning while valuing others' perspectives","items":[{"code":"COM.3.1A","levels":[["9316dea9-2ffb-50d8-8885-d14073b2e5fd","Notices that people may need additional time or support to express themselves."],["0178c053-705a-540f-8bdf-8ca6511f18b9","Allows others to express themselves (e.g., pausing for breaks before speaking)."],["6bba9b7a-22b9-5bf0-9e14-89732e06d2fe","Elevates others' efforts to express themselves while showing care or concern (e.g., pausing for breaks before speaking, asking for clarification)."],["e7c0ebc4-cc18-5781-8f8a-a28047501e41","Anticipates and responds to others' needs during conversation, using timing and presence to support thoughtful expression."]]},{"code":"COM.3.1B","levels":[["4341d5c5-205c-5773-8097-15f96cf39d2f","Demonstrates focus during some parts of an interaction, for example, by using nonverbal features of expression (e.g., reasonable facial expressions, gestures, body language)."],["ba6e4194-3c69-5cbe-8dd1-cc1b30253d2d","Conveys interest to others during interactions with minimal distraction for example, by using features of expression that are verbal (e.g., words or sounds to encourage the listener to continue) or nonverbal (e.g., reasonable facial expressions, gestures, body language)."],["e94c2c08-3ce7-5ce2-8aad-f80166dd78be","Conveys sustained interest to others during interactions using features of expression that are verbal (e.g., words or sounds to encourage the listener to continue) or non-verbal (e.g., reasonable facial expressions, gestures, body language) to affirm identity, experience and emotion."],["9e315044-3363-52e1-a8c7-af6ffedeaaec","Adjusts listening approach in real time to remain fully engaged across diverse conversational styles or emotional dynamics whether verbal (e.g., words or sounds to encourage the listener to continue) or nonverbal (e.g., reasonable facial expressions, gestures, body language) to affirm identity, experience and emotion."]]},{"code":"COM.3.1C","levels":[["98cb2812-7953-553c-9c68-e9594c41f910","Recognizes and values differences in a speaker's manner of expression, which might seem unfamiliar (e.g., due to differences in accent, dialect, words or phrases)."],["8c951517-0e30-5e5c-98cf-9d54d2577325","Recognizes and values differences in a speaker's manner of expression and further identifies the essential content of a message."],["7a5a3f92-9077-56ee-ab4f-b546208039cb","Recognizes and values differences in a speaker's manner of expression to further understand and relate to the message."],["22e7b1f1-e6a4-5f0a-a605-79526dcffa04","Integrates understanding of communication differences to build stronger cross-cultural and interpersonal connections."]]}]},{"id":"455bc3fc-778e-54c9-a75f-307d8af328e1","code":"COM.3.2","description":"Identify and comprehend key information that has been conveyed by others","items":[{"code":"COM.3.2A","levels":[["6dbf3239-5390-5b1a-bc07-19669966793b","Recognizes that verbal and nonverbal cues can convey meaning in an interaction (e.g., nodding or gestures)."],["1313ebf9-5e04-5e1d-a78d-b209fa3e3752","Understands meaning conveyed by verbal and nonverbal cues (e.g., gestures such as nodding)."],["bd4c5b88-2eeb-5395-a318-a901b4802c91","Understands meaning conveyed by combinations of verbal and nonverbal cues (e.g., gestures such as nodding)."],["39c218de-a4a6-5749-b338-f38b3bad79fa","Understands meaning conveyed by combinations of verbal and nonverbal cues (e.g., gestures such as nodding) across a range of contexts/scenarios."]]},{"code":"COM.3.2B","levels":[["d3977163-4f52-546a-9663-0a85d47a637a","Records notes reflecting some key information during conversations or discussions."],["a95028b1-4944-54f8-b208-bbc62e38a4cb","Records notes and summarizes key information during conversations or discussions."],["24b455c0-e281-50bb-968b-6647608ce4ff","Records detailed and organized notes during longer discussions and synthesizes key information during extended conversations or discussions."],["0a1e909e-3509-51cc-811e-62f9d8e2dd91","Records detailed and organized notes during longer discussions and synthesizes key information during extended conversations or discussions, including points of synergy or discrepancy in discussion, and across both verbal and nonverbal communication repertoires used."]]},{"code":"COM.3.2C","levels":[["4dfcbca1-d61b-549f-8882-8a4c6fd280be","Identifies most key ideas from conversations or discussions."],["ff921d25-d218-527f-88de-5f6df103ddd8","Identifies main ideas in a conversation or discussion and can separate them from less important details."],["f58d142e-9642-5f8d-a1ea-7bfc64634ab5","Identifies and explains main ideas and supporting details during extended conversations or discussions."],["9cd3dbfa-e84b-556d-83d7-02c40aeac4ae","Identifies and explains main ideas and supporting details during extended conversations or discussions across a wide range of speakers and perspectives."]]}]},{"id":"1ca12679-4bed-5dd4-864a-5fe6c8be8e7a","code":"COM.3.3","description":"Seek clarification from others to resolve ambiguity or uncertainty","items":[{"code":"COM.3.3A","levels":[["2687d1d6-ae08-5e90-ad59-34bae69257b6","Notices when a message is not understood."],["384014bc-0047-59a4-aaac-f91a07dd95c9","Notices when a message is not understood and identifies parts that are likely sources of confusion."],["9a3d3e7a-9ad0-59c7-a924-377a1b63f060","Notices when clarity is needed in an interaction with others and works to resolve confusion by restating or asking clarifying questions."],["3d722be4-750b-52fa-a447-bf4ed0adba3b","Notices when clarity is needed in an interaction with others and works to resolve confusion by restating or asking clarifying questions, inviting others to raise questions and confirming shared understanding."]]},{"code":"COM.3.3B","levels":[["1630f1b4-cc39-5a31-87ab-9b4c14d16228","Generates questions that could help clear up confusion or provide more information."],["87b190aa-a8d4-519a-a9f6-d75dab602c15","Formulates specific and clear questions likely to help resolve any ambiguities or uncertainties."],["33e806ff-5f84-5d34-9322-594d125b17b9","Formulates questions to help resolve specific ambiguities or uncertainties to attain a deeper understanding of the message."],["e0d73326-ad80-53d1-b2f7-e0a7822ec3c9","Formulates questions to guide group inquiry related to ambiguities or uncertainties, and elevates collective insight of the message or issues contributing to the uncertainties."]]},{"code":"COM.3.3C","levels":[["21c299a6-1564-5b97-8849-316c341b6dc0","Demonstrates effort to ask questions during conversations or discussions."],["deee5ee9-f620-516d-905f-f925d94c23ee","Asks questions during conversations or discussions."],["bd077234-6f9d-51b6-ba20-98299fee94d5","Asks thoughtful questions during conversations or discussions, even in challenging or fast-paced situations."],["1b1e14a4-7e79-56ab-b8b7-1c1f1172c700","Adapts tone, timing and phrasing to ask thoughtful questions in response to complex or sensitive points in challenging discussions."]]}]},{"id":"4aa646ac-9c6b-5103-baa4-8ccc5a1279f4","code":"COM.3.4","description":"Demonstrate understanding of a message beyond what is directly stated","items":[{"code":"COM.3.4A","levels":[["0ec3cf20-2643-58da-853a-d6c010f78943","Recognizes that information can be implied in a message without being directly stated."],["e26c2172-ddcd-5964-833b-1e5cb69db8ca","Identifies some implied information in a message."],["7a3e53b3-3922-57cf-b326-1ef6d93e7581","Identifies implied information and explains how it changes the interpretation of the deeper meaning of the message."],["854385b4-1efb-5711-a3a1-528709b31c15","Evaluates how implied meaning varies across audiences and contexts, adjusting the interpretation of a message accordingly."]]},{"code":"COM.3.4B","levels":[["f7da5ced-400e-5775-ada3-bb296c49ddd9","Notices when a message may include hidden or indirect meaning."],["bdc78b10-10a5-538c-be97-c5e1c1e1edf5","Identifies both the direct and plausible implied meanings."],["a687b42b-4bb6-5d0f-b9e7-d8bc8dd3f57d","Analyzes the message for both direct and implied meanings and reflects on how the overarching meaning may vary across contexts or audiences."],["f8bd911c-bfd8-59b2-94ad-23247cb10cbd","Analyzes the message across a range of contexts and scenarios for both direct and implied meanings and reflects on how the overarching meaning may vary across contexts or audiences."]]},{"code":"COM.3.4C","levels":[["e88cf758-6173-5e49-8b0d-c2d1c14b21e6","Recognizes that the context of a conversation can shape how a message should be interpreted."],["24f9e8dd-f514-59b9-9803-0e07fad17f9a","Observes features of the context that affect the plausible interpretation of a message."],["cc806824-9679-52a7-ae59-8d1c289cb50a","Identifies and describes features of the context that affect a plausible interpretation of a message and its deeper meaning."],["8d0569bb-1e87-5993-816c-60c368e23891","Synthesizes personal and cultural perspectives to interpret meaning with empathy and precision."]]}]}]},{"code":"COM.4","description":"Understand and leverage the social, emotional and ethical dimensions of communication","indicators":[{"id":"a72a59d3-6eeb-5791-bdc3-e111c90f4e0c","code":"COM.4.1","description":"Maintain a respectful and inclusive environment for understanding and resolving conflict","items":[{"code":"COM.4.1A","levels":[["c759c5c0-030d-5c67-bfd6-006493412e7e","Regulates responses during disagreements and engages respectfully with others."],["740c9980-a212-553b-b9b2-9cc1c943fc98","Maintains composure, demonstrates self-awareness, acknowledges personal bias and actively supports respectful dialogue to resolve conflicts."],["c03287be-6b14-55a4-88dd-eefbc6cc59dd","Maintains composure, demonstrates self-awareness, acknowledges personal bias and encourages others to share views during disagreements, promoting civility and resolution."],["816b77df-c914-5708-95db-0135fde68113","Anticipates moments of tension and guides group dialogue toward respectful and inclusive resolution."]]},{"code":"COM.4.1B","levels":[["226f9d0d-047a-5698-a176-90b7026ff7d4","Recognizes that disagreements often have different sides."],["1934ccf0-3b5c-5d0a-af35-c49bd740525b","Demonstrates understanding of the different sides in disagreements."],["b6209f0c-3cdf-5e02-9b42-281917cdf7ec","Considers and explains multiple sides of a disagreement."],["08629838-5277-5958-9235-0e7c29de1773","Considers diverse perspectives contributing to a disagreement and explains how different perspectives may arise, acknowledging differences in lived experience, values and ideas."]]},{"code":"COM.4.1C","levels":[["e5da9318-50c5-5ad4-b9e4-e39919e2a6be","Recognizes the importance of figuring out the root causes of conflicts."],["e8ef1ba9-8994-5e03-8b19-7b3f78a8d2c9","Identifies root causes and uses strategies (e.g., seeking shared understanding) to resolve conflicts."],["e7c2472e-dc6b-5ed5-9215-63f7634f1a8c","Identifies root causes, applies strategies to resolve conflicts without clear solutions or resolutions (e.g., identifying and navigating trade-offs), adapting resolution strategies based on contextual features (e.g., group dynamics, history, complexity)."],["5039fc95-12d3-5cba-88d4-d8ce86221d4a","Identifies root causes, applies strategies to resolve complex conflicts, and helps others avoid similar issues in the future."]]}]},{"id":"f384343b-6263-55f9-ae4b-63c0b0459e21","code":"COM.4.2","description":"Understand others' emotions during conversations","items":[{"code":"COM.4.2A","levels":[["22fcec7b-f6c0-5eac-a939-f98ef394f830","Notices that others may convey emotions during conversations."],["86148efd-abfa-5e5c-b3db-87fad8444947","Recognizes specific types of emotions during conversations and tries to understand others' feelings."],["0436717e-16be-5ba9-ab9c-41d638046f01","Recognizes emotions, even when not clearly expressed (e.g., sarcasm, hidden feelings)."],["bed5ff99-3835-572a-932d-7f9da7db6e54","Recognizes emotional shifts in conversation, reads multiple layers of emotion in real time, and adapts accordingly."]]},{"code":"COM.4.2B","levels":[["9dc24de2-de4a-5782-a011-cc580d999114","Notices nonverbal cues are likely to convey others' emotions (e.g., facial expressions, body language, sentiment cues in digital communication)."],["c53e9420-4e3a-59fe-b5e6-38930375594a","Identifies specific nonverbal cues that convey emotions (e.g., facial expressions, body language, sentiment cues in digital communication)."],["ac6e90e7-9a97-531f-8615-cbd36cbdb897","Explains how nonverbal cues convey emotions (e.g., facial expressions, body language, sentiment cues in digital communication) in a given context."],["332c0025-8db8-5f5d-87e7-4a989496464e","Models emotional reflection to nonverbal cues (e.g., facial expressions, body language, sentiment cues in digital communication) by naming and validating others' experiences in ways that deepen relational trust."]]},{"code":"COM.4.2C","levels":[["5a517f4d-7e6f-54c5-ad34-0fb3e5fd615e","Recognizes the importance of responding respectfully (e.g., avoiding sarcasm or dismissive behavior)."],["567b12ce-f917-5f26-978c-f8b543e08021","Responds to others in a manner that demonstrates empathy (e.g., by relating one's experience to that of others)."],["02ea2537-dc0a-5041-be8d-b418bd39cd61","Demonstrates understanding of others' emotions by responding in ways that are empathetic and culturally appropriate."],["0961f23e-42ac-5cb1-9ec6-b936364882e8","Models empathetic responses in emotionally complex interactions, showing an understanding of how communication that conveys care may vary across individuals and contexts."]]}]},{"id":"1eab2c28-63f9-58a9-ac65-3c1f7a5246da","code":"COM.4.3","description":"Express emotions intentionally and empathetically","items":[{"code":"COM.4.3A","levels":[["1c42b6c4-5acc-5951-afb4-5d5b2a1a07f8","Recognizes and names their emotions (positive or negative) when communicating with others."],["c01201d7-638e-51fe-a58c-cc6a6ea06a8f","Explains their emotions to help others understand their feelings."],["c7c05149-9a4b-574f-80c6-f4490534fed4","Explains their emotions and why they feel that way to build better understanding with others."],["560496de-a971-5d79-b119-0c130dd9c3ee","Demonstrates emotional self-awareness by communicating with clarity, vulnerability and relational intentionality."]]},{"code":"COM.4.3B","levels":[["84926cc0-4a55-5069-805a-093b4198476f","Recognizes that their emotions affect how they interact with others."],["50405695-c0d0-5f10-8497-f2621f448053","Recognizes how they usually share emotions and demonstrates effort to control their reactions in a constructive manner."],["435994b4-cceb-58e3-8d4f-793f1ac38e3b","Anticipates emotional impact and adapts expression to support respectful and effective dialogue while authentically communicating their personal feelings."],["c2f733de-3f05-57e6-ab9a-9802188a4823","Adjusts how they express emotions to improve conversations and explains strategies for empathetic communication."]]},{"code":"COM.4.3C","levels":[["4be4a960-c873-52d8-ad16-4e6a05d0dd7c","Expresses simple emotions reasonably during conversations (e.g., facial expressions such as smiling, verbally conveying sentiment)."],["aa8179db-5353-5d3d-80ec-15e02569d449","Expresses emotions and adjusts their manner of expression if they think their emotions are misunderstood."],["fade0c5c-6dfe-5dfc-adb5-10b0c6dde753","Expresses emotions in a way that others can understand and clarifies if emotions are misunderstood, showing care not to dismiss others."],["a5c7ef47-7b29-5d20-9a04-492c5c32086d","Adapts expression across different settings, cultures and communication styles. Models emotional awareness by validating others' feelings while being honest about their own."]]}]},{"id":"12e478b2-67b9-52dd-855a-e33882200458","code":"COM.4.4","description":"Adapt communication with awareness of how different language, cultural norms and communication styles shape meaning","items":[{"code":"COM.4.4A","levels":[["19a72054-b714-5dfe-8242-467010e7d553","Recognizes that respect and civility are important for communication in a variety of contexts, particularly cross-cultural contexts."],["9bd24bae-f81e-5998-91c1-50366602813b","Identifies behaviors that are seen as respectful in cross-cultural contexts and acts accordingly."],["2c1d90c0-04f5-5355-bbf0-f18a74cdabab","Relates familiar behaviors with new ones relevant to cross-cultural contexts and explains to others how to behave and communicate accordingly."],["a7afc9be-d282-5571-bbe1-fb8b9e6a6547","Navigates behavior across diverse cultural settings with curiosity and care, even when norms are unfamiliar."]]},{"code":"COM.4.4B","levels":[["38ca7a86-6584-533c-981e-33953dc1e776","Understands that cultural practices (e.g., language, traditions) affect how people communicate (e.g., accents, terms, gestures)."],["ab3c138f-b12b-59c4-8dc7-c20809b491e6","Adapts communication style to align with cultural norms and practices."],["6bb3a718-fecd-5b69-abe3-344ca618339f","Adapts communication style in response to specific cultural norms while recognizing that some situations may involve complex cultural practices."],["6cdc2131-3953-5ceb-b70a-bab2ff2a213f","Evaluates and adjusts communication strategies to build understanding in complex or layered cultural contexts."]]},{"code":"COM.4.4C","levels":[["2db8532e-375d-5d26-84c2-a071cecdafd5","Demonstrates awareness of a lack of knowledge about cultural differences in how people communicate (e.g., reasonably expressing confusion)."],["0d038dcc-fc51-58dc-a76e-9e7ae234accc","Demonstrates curiosity about cultural differences in social and historical influences on how people communicate (e.g., by asking reasonable questions)."],["77fc0504-dd85-5444-83dd-2ab296522858","Applies and continues to learn new knowledge of the social, cultural and historical influences on language to improve communication and build stronger relationships with others."],["b6d475c2-d2df-5d05-896d-7bd9f49224b2","Supports peers in understanding and navigating cultural or linguistic differences in communication."]]}]}]}]},{"code":"CT","name":"Critical Thinking","description":"Critical thinking involves the skill and disposition to actively seek and evaluate information and construct evidence-based arguments to reach well-founded conclusions or informed decisions, including recognizing and applying sound logical reasoning. It plays an important role in learning activities, such as evaluating multiple sources, identifying assumptions and reasoning flaws, and making sound arguments. Developing strong critical thinking skills enables students to tackle complex challenges more effectively and achieve greater learning outcomes.","subskills":[{"code":"CT.1","description":"Information Seeking","indicators":[{"id":"700ef526-2a3c-5fba-a259-fa263016448c","code":"CT.1.1","description":"Formulate relevant questions to address gaps in information (“ask the right questions”)","items":[{"code":"CT.1.1A","levels":[["43d4d305-aff4-5d3f-808a-a56191779fef","Identifies when more information is needed and asks questions with coaching."],["43a7a3d3-e2ee-5819-9557-bfb8c8063992","Ask questions to clarify or confirm pre-existing information."],["97ec197f-2dce-5c88-9774-57ad8e9b1996","Asks questions to explore gaps in information or to gather new relevant information on a topic."],["ee5f8719-0149-56ff-9ba9-d4d6ada890f7","Asks thought-provoking questions that guide the gathering of relevant information, support conclusions and inform further exploration or questioning in novel ways."]]},{"code":"CT.1.1B","levels":[["54d632af-d71b-556e-8373-97cbfb7e2095","Identifies when more information is needed and asks questions with coaching."],["04d00b0d-c1ce-5ce3-bebe-a27f09a37eeb","Asks questions related to the basic elements of a topic."],["667078a7-5b98-5b97-8803-55f3288b6df4","Asks questions about details beyond the basic elements of a topic."],["c554c295-a329-589e-b5a3-812c73191df4","Asks questions related to gaps in information that have not been answered by experts or other knowledgeable sources."]]}]},{"id":"08ee2db3-d04e-548c-bbcf-d93839634820","code":"CT.1.2","description":"Pursue multiple, credible, relevant sources of information","items":[{"code":"CT.1.2A","levels":[["011d7c52-12dc-51c8-aee6-1e66864e021b","Seeks out sources of information."],["9e5793a5-5be7-591d-b1b1-a2f1345e4279","Uses basic search terms to locate a relevant source."],["6189097e-d9e1-563f-b3ff-9d74aa6d8cb0","Uses various search terms to locate multiple relevant sources, some of which are credible."],["d2062496-89d6-5c39-a19c-76a206936443","Uses various search terms to locate multiple relevant sources, most or all of which are credible as evaluated by their content."]]},{"code":"CT.1.2B","levels":[["6ced14c9-8c01-5927-9f49-1cc938abcf73","Uses one familiar and/or commonly used source to obtain information."],["d370e0ed-e4df-5974-b738-c45866405a59","Uses only familiar and/or commonly used sources to obtain relevant information."],["e30aed37-a76c-5ebf-88c2-285fcf27ff92","Uses a combination of familiar and unfamiliar sources to obtain relevant information."],["d455c6d1-e78a-5ca3-9d80-d1d1855d98f9","Uses credible unfamiliar sources to expand upon relevant information from credible sources."]]}]},{"id":"6f1b7865-63cd-537b-8429-5a8bddd8bf75","code":"CT.1.3","description":"Fact-check claims and ideas","items":[{"code":"CT.1.3A","levels":[["306e5364-69f5-575d-a724-ee6959deab3d","Fact-checks information randomly."],["f8b1a5aa-442e-51fb-ae52-9a9aa431bcbd","Fact-checks claims and ideas only when information is missing."],["c48679b7-d5f2-574a-aa9f-8e556505e3bf","Fact-checks claims and ideas that are only supported by arguments and/or unscientific or informal evidence (e.g., anecdotal)."],["cc7b0ab7-d540-5a31-a537-04fde16858f8","Fact-checks claims and ideas even if they are supported by formal, scientific, technical and/or statistical evidence."]]},{"code":"CT.1.3B","levels":[["20c2d7d6-7478-5b0d-9801-b7bd95121c5a","Fact-checks information randomly."],["436bd4f0-31af-5ab8-b0aa-25cbf587814c","Fact-checks claims and ideas only when the source appears less credible or more biased."],["642bda01-aea3-5808-aa3a-62099a80866c","Selectively fact-checks claims and ideas, regardless of whether the source appears less credible or more biased."],["7db36b49-dac0-5e33-84ca-2b822b49ac3e","Efficiently and accurately fact-checks claims and ideas even when the source appears credible and unbiased."]]}]}]},{"code":"CT.2","description":"Information Analysis","indicators":[{"id":"535603c1-16bd-51c4-be54-65f31938b23f","code":"CT.2.1","description":"Effectively synthesize multiple pieces of information","items":[{"code":"CT.2.1A","levels":[["d46fb2ad-6ec2-5ac8-9958-3913c466e692","Summarizes key or main ideas from one source."],["0a6d9e6e-dd47-5905-8485-24bf22ff0e51","Summarizes information from multiple sources."],["743e1ce8-61d7-549d-afb0-ea60d1e03860","Integrates information from multiple sources to identify relationships and patterns."],["4f58c1fe-36d6-586d-99e1-f4f5cadc6c7e","Integrates information from multiple sources of information to form a comprehensive understanding of a topic, leading to deeper (possibly unique) insights and connections."]]},{"code":"CT.2.1B","levels":[["4a152c1c-24fb-545c-a9b3-d25b8e52df8f","Identifies basic features of a source (e.g., source, date, author)."],["52079abf-85c7-5d4d-940f-62e3070e1e62","Categorizes information from multiple sources based on foundational and/or surface-level elements (e.g., source, date)."],["e4edeb33-5535-5e14-a9e0-218a689978a1","Integrates information from multiple sources to compare and construct different viewpoints."],["96f59459-7683-58d5-888f-2c49326b2bae","Integrates information from multiple sources in a way that generates new questions, applications and/or implications."]]}]},{"id":"dc8b48c2-d2cb-5d66-88d7-381fe9655da6","code":"CT.2.2","description":"Evaluate the strength of evidence used to form a conclusion","items":[{"code":"CT.2.2A","levels":[["3b2a142a-8107-541c-bee2-4562a4d16ae8","Identifies evidence used to support a conclusion."],["9e72a5dc-b46d-525d-9524-66ffcc1ae2af","Recognizes when evidence is relevant to a conclusion."],["afafe37a-8020-5e00-b90b-0cbfe5f4d3f3","Distinguishes between weaker and stronger evidence used to form a conclusion."],["71097eca-f9a8-532d-9761-b8ab8297ea44","Distinguishes between weaker and stronger evidence used to form a conclusion and can articulate specific and defensible explanations for their evaluation."]]},{"code":"CT.2.2B","levels":[["5040a2af-83b4-5fa2-b642-90252179d30c","Identifies evidence used to support a conclusion."],["b935ea2a-5064-5e36-bdbf-26004a6c15bb","Articulates whether evidence is relevant or irrelevant to a conclusion."],["54fca970-77f5-5a90-a5a6-927c89d2a166","Accurately articulates whether evidence is relevant or irrelevant to a conclusion."],["c956df2f-270d-5034-80e8-f5a506a792a7","Articulates whether evidence is relevant or irrelevant to a conclusion and provides an accurate explanation for their evaluation."]]}]}]},{"code":"CT.3","description":"Argument Generation","indicators":[{"id":"8611896c-d8fd-525d-a445-27d27092d917","code":"CT.3.1","description":"Effectively address counterarguments","items":[{"code":"CT.3.1A","levels":[["81a74b7e-cbc2-5d66-a4a5-ebdc797de82f","Identifies basic opposing viewpoints or counterarguments."],["19c0e3c3-7643-5a46-83b9-0ff7be95c377","Explains opposing viewpoints or counterarguments."],["35d8f652-e3f5-5fdc-904e-6621cf4692db","Identifies different perspectives and potential counterarguments and develops responses to the opposing view."],["3a7400ea-47ac-5431-9dad-8160b3babe2f","Evaluates counterarguments, refuting them when appropriate or considering them when they are reasonable; integrates multiple relevant perspectives into a coherent and reasonable argument (recognizing the value in diverse viewpoints)."]]},{"code":"CT.3.1B","levels":[["cbf3a116-a330-5d04-affc-3ee6aa588135","Identifies basic opposing viewpoints or counterarguments."],["afc2120b-dcbe-5537-b4c8-71acc1d8c224","Differentiates between arguments that oppose or support their argument."],["a44ba8fd-f6a1-5254-ac0a-a95cbc447d32","Recognizes when counterarguments are not relevant to their own argument."],["12b79a97-4827-5375-9bab-e3988f6b5e41","Recognizes when counterarguments are not relevant to their own argument and articulates why."]]}]},{"id":"78d4448b-18f5-546a-8124-8edc52f3a992","code":"CT.3.2","description":"Rely on evidence, data and/or facts over opinions","items":[{"code":"CT.3.2A","levels":[["2f03b18c-5d19-5357-8711-914f663ff110","Differentiates between a fact and an opinion in authentic materials."],["7e9a55a7-57a0-5f47-85c4-eca977847dd1","Understands the difference between a fact and an opinion when developing arguments."],["b3318acc-8ffe-5abe-a680-8048bec30b4e","Prioritizes facts over opinions when developing arguments, drawing conclusions or suggesting course of action."],["c18d7e4e-dadf-5a4e-8dbc-fce6d4f59c43","Constructs a coherent argument that prioritizes facts over opinions and integrates source citations in the argument (e.g., in-text citations, sources of evidence, data or facts)."]]}]}]},{"code":"CT.4","description":"Logical Reasoning","indicators":[{"id":"c6da0028-7652-55c0-8b05-4d1062d8357f","code":"CT.4.1","description":"Draw specific conclusions from general statements (i.e., apply deductive reasoning)","items":[{"code":"CT.4.1A","levels":[["08df06c1-2fba-5bab-ad04-ddf27662ee1b","Applies simple deductive reasoning with support."],["5089d5fb-b61e-5a2b-acf4-9881df9afff1","Independently applies deductive reasoning (i.e., draws a specific conclusion from a general statement) to analyze simple and straightforward relationships/arguments (e.g., in familiar contexts)."],["c7099c25-260f-5b3c-9052-3bbc3240b690","Uses valid assumptions (e.g., factually correct claims) to apply deductive reasoning in novel or complex contexts (i.e., draw a specific conclusion from a general statement to analyze complex relationships/arguments)."],["a640b6aa-1c0e-5974-8a26-c142a38f5969","Uses valid assumptions to apply deductive reasoning to analyze complex relationships/arguments and articulate the relationships/arguments accurately (e.g., assumptions, evidence, claims)."]]},{"code":"CT.4.1B","levels":[["3186d0e3-0377-505f-a5f2-9654edcdb6e9","Applies simple deductive reasoning with support."],["5cf58e35-83ec-59f4-8f64-5ad9bd3f152f","Recognizes when others are using deductive reasoning in simple, straightforward or familiar contexts."],["df3df0ca-e6ea-5ea3-805c-20ccc8c6fc0b","Recognizes when others are using valid assumptions to support deductive reasoning."],["f39c2ac7-8ae0-55a1-9349-691a2095eefd","Recognizes when others use valid assumptions to apply deductive reasoning to analyze complex relationships/arguments, and articulate the relationships/arguments accurately (e.g., assumptions, evidence, claims)."]]}]},{"id":"2b30549d-3600-5aff-b835-21f66953253f","code":"CT.4.2","description":"Recognize and avoid logical fallacies","items":[{"code":"CT.4.2A","levels":[["77c621ca-f99d-5ae9-8b6c-3e20fc342230","Recognizes examples of logical fallacies."],["70a01e5c-f385-5243-9017-2ba1983accd9","Recognizes common logical fallacies in others' arguments."],["111d5bdc-584e-5108-ab15-7f6a34957c17","Recognizes most logical fallacies in others' arguments."],["d7b8fd15-1b5d-5ccb-8557-cf0e0fff6eb7","Recognizes most or all logical fallacies in others' arguments, including articulating the nature of these fallacies (e.g., causation fallacy, false equivalency)."]]},{"code":"CT.4.2B","levels":[["00a6824f-73a2-5091-8f65-43075dfe5520","Recognizes examples of logical fallacies."],["95dc6543-3940-5c09-9d3b-3d1d21146165","Avoids common logical fallacies when generating arguments."],["5b06fe30-88f9-5a08-b19e-e6f1ed60f985","Avoids most logical fallacies when generating arguments."],["48268490-00dc-5f63-8b64-de4947ae6da7","Avoids most or all logical fallacies when generating arguments, including articulating the nature of these fallacies (e.g., causation fallacy, false equivalency)."]]}]}]}]}]};
